public IReadOnlyList<DesktopWindowInfo> GetScriptRecordingWindows()
{
    if (CurrentController != MaaControllerTypes.Win32) return Array.Empty<DesktopWindowInfo>();
    var windows = MaaProcessor.Toolkit.Desktop.Window.Find().Where(window => !string.IsNullOrWhiteSpace(window.Name)).ToList();
    var (index, filtered) = CalculateWindowIndex(windows, CurrentController);
    if (index > 0 && index < filtered.Count)
    {
        var selected = filtered[index];
        filtered.RemoveAt(index);
        filtered.Insert(0, selected);
    }
    return filtered;
}

